import { mkdir, readFile, writeFile } from "node:fs/promises";

const outDir = "artifacts";
await mkdir(outDir, { recursive: true });

// Load all negative test results
const accessPassNegative = JSON.parse(await readFile(`${outDir}/access-pass-negative-cases.json`, "utf8"));
const treasuryNegative = JSON.parse(await readFile(`${outDir}/treasury-negative-cases.json`, "utf8"));

// These will be generated by the test scripts
let escrowNegative = null;
let batchNegative = null;
let walletNegative = null;

try {
  escrowNegative = JSON.parse(await readFile(`${outDir}/escrow-negative-cases.json`, "utf8"));
} catch (err) {
  console.warn("escrow-negative-cases.json not yet generated (run test-escrow-negative.mjs first)");
}

try {
  batchNegative = JSON.parse(await readFile(`${outDir}/batch-assurance-negative-cases.json`, "utf8"));
} catch (err) {
  console.warn("batch-assurance-negative-cases.json not yet generated (run test-batch-assurance-negative.mjs first)");
}

try {
  walletNegative = JSON.parse(await readFile(`${outDir}/wallet-negative-cases.json`, "utf8"));
} catch (err) {
  console.warn("wallet-negative-cases.json not yet generated (run test-wallet-negative.mjs first)");
}

// Build consolidated matrix
const matrix = {
  schema: "tn12-negative-test-matrix/v1",
  generatedAt: new Date().toISOString(),
  status: "negative-test-matrix-ready",
  summary: {
    totalTestSuites: 5,
    totalCases: 0,
    totalCorrectlyRejected: 0,
    legitimatePathsPass: 0,
    legitimatePathsTotal: 0
  },
  suites: []
};

// Add access-pass
if (accessPassNegative) {
  matrix.suites.push({
    name: "access-pass",
    status: accessPassNegative.status,
    cases: accessPassNegative.cases?.length || 0,
    correctlyRejected: accessPassNegative.cases?.filter((c) => c.observed === "rejected").length || 0
  });
  matrix.summary.totalCases += accessPassNegative.cases?.length || 0;
  matrix.summary.totalCorrectlyRejected += accessPassNegative.cases?.filter((c) => c.observed === "rejected").length || 0;
}

// Add treasury
if (treasuryNegative) {
  matrix.suites.push({
    name: "treasury",
    status: treasuryNegative.status,
    cases: treasuryNegative.cases?.length || 0,
    correctlyRejected: treasuryNegative.cases?.filter((c) => c.observed === "rejected").length || 0
  });
  matrix.summary.totalCases += treasuryNegative.cases?.length || 0;
  matrix.summary.totalCorrectlyRejected += treasuryNegative.cases?.filter((c) => c.observed === "rejected").length || 0;
}

// Add escrow
if (escrowNegative) {
  matrix.suites.push({
    name: "escrow",
    status: escrowNegative.status,
    cases: escrowNegative.cases?.length || 0,
    correctlyRejected: escrowNegative.cases?.filter((c) => c.observed === "rejected").length || 0,
    legitimatePaths: escrowNegative.summary?.legitimatePathsPass || 0
  });
  matrix.summary.totalCases += escrowNegative.cases?.length || 0;
  matrix.summary.totalCorrectlyRejected += escrowNegative.cases?.filter((c) => c.observed === "rejected").length || 0;
  matrix.summary.legitimatePathsPass += escrowNegative.summary?.legitimatePathsPass || 0;
  matrix.summary.legitimatePathsTotal += escrowNegative.summary?.legitimatePathsTotal || 0;
}

// Add batch-assurance
if (batchNegative) {
  matrix.suites.push({
    name: "batch-assurance",
    status: batchNegative.status,
    cases: batchNegative.cases?.length || 0,
    correctlyRejected: batchNegative.cases?.filter((c) =>
      c.observed && (c.observed.includes("rejected") || c.observed.includes("mismatch") || c.observed.includes("multiple"))
    ).length || 0,
    legitimatePaths: batchNegative.summary?.legitimatePathsPass || 0
  });
  matrix.summary.totalCases += batchNegative.cases?.length || 0;
  matrix.summary.totalCorrectlyRejected += batchNegative.cases?.filter((c) =>
    c.observed && (c.observed.includes("rejected") || c.observed.includes("mismatch") || c.observed.includes("multiple"))
  ).length || 0;
  matrix.summary.legitimatePathsPass += batchNegative.summary?.legitimatePathsPass || 0;
  matrix.summary.legitimatePathsTotal += batchNegative.summary?.legitimatePathsTotal || 0;
}

// Add wallet
if (walletNegative) {
  matrix.suites.push({
    name: "wallet",
    status: walletNegative.status,
    cases: walletNegative.cases?.length || 0,
    correctlyRejected: walletNegative.cases?.filter((c) =>
      c.observed && (c.observed.includes("rejected") || c.observed.includes("unsigned") ||
                     c.observed.includes("local-key") || c.observed.includes("double-spend") ||
                     c.observed.includes("mismatch") || c.observed.includes("missing") ||
                     c.observed.includes("lost") || c.observed.includes("invalid"))
    ).length || 0,
    legitimatePaths: walletNegative.summary?.legitimatePathsPass || 0
  });
  matrix.summary.totalCases += walletNegative.cases?.length || 0;
  matrix.summary.totalCorrectlyRejected += walletNegative.cases?.filter((c) =>
    c.observed && (c.observed.includes("rejected") || c.observed.includes("unsigned") ||
                   c.observed.includes("local-key") || c.observed.includes("double-spend") ||
                   c.observed.includes("mismatch") || c.observed.includes("missing") ||
                   c.observed.includes("lost") || c.observed.includes("invalid"))
  ).length || 0;
  matrix.summary.legitimatePathsPass += walletNegative.summary?.legitimatePathsPass || 0;
  matrix.summary.legitimatePathsTotal += walletNegative.summary?.legitimatePathsTotal || 0;
}

matrix.summary.completeness = `${matrix.suites.length}/${matrix.summary.totalTestSuites} test suites`;
matrix.summary.rejectionRate = matrix.summary.totalCases > 0
  ? `${matrix.summary.totalCorrectlyRejected}/${matrix.summary.totalCases} (${Math.round((matrix.summary.totalCorrectlyRejected / matrix.summary.totalCases) * 100)}%)`
  : "pending";

await writeFile(`${outDir}/negative-test-matrix.json`, JSON.stringify(matrix, null, 2));
console.log("✓ Negative test matrix generated:", `${outDir}/negative-test-matrix.json`);
console.log(`  Suites: ${matrix.suites.length}/${matrix.summary.totalTestSuites}`);
console.log(`  Total cases: ${matrix.summary.totalCases}`);
console.log(`  Rejection rate: ${matrix.summary.rejectionRate}`);
console.log(`  Legitimate paths: ${matrix.summary.legitimatePathsPass}/${matrix.summary.legitimatePathsTotal}`);
